import { useState } from 'react';
import { Button } from '@plexui/ui/components/Button';

export default function ButtonStatesExample() {
  const [disabled] = useState(false);
  const [loading] = useState(false);
  const variants = ['solid', 'soft', 'outline', 'ghost'] as const;

  return (
    <>
      {/* Desktop: a row of the default size */}
      <div className="flex flex-wrap gap-3">
        {variants.map((variant) => (
          <Button key={variant} color="primary" variant={variant} disabled={disabled} loading={loading}>
            {variant.charAt(0).toUpperCase() + variant.slice(1)}
          </Button>
        ))}
      </div>

      {/* Phone: a screen's actions, as wide as the screen */}
      <div className="flex w-full flex-col items-center gap-[11px]">
        {variants.map((variant) => (
          <Button key={variant} color="primary" variant={variant} size="xl" block disabled={disabled} loading={loading}>
            {variant.charAt(0).toUpperCase() + variant.slice(1)}
          </Button>
        ))}
      </div>
    </>
  );
}

