        onChange={(event) => setName(event.target.value)} />
    </Dialog.Body>
  )}
  <Dialog.Footer mobileLayout={stacked ? 'stacked' : undefined}>
    {actions === '1' && main}
    {actions === '2' && <>{cancel}{main}</>}
    {actions === '3' && (
      <>
        {main}
        <Button color="danger" variant="soft" onClick={() => setOpen(false)}>Don’t Save</Button>
        {cancel}
      </>
    )}
  </Dialog.Footer>
</Dialog.Content>
</Dialog>

