import { toast, compact as compactOptions } from "@plexui/ui/components/Toast"

// Each type's title, its short description and its action's label
const messages = {
default: { title: "Changes saved", description: "Your profile is live for everyone on the team.", action: "Undo" },
success: { title: "Inquiry ID copied", description: "Paste it into the support form.", action: "Open" },
error: { title: "Failed to assign owner", description: "The owner has left the workspace.", action: "Retry" },
warning: { title: "Session expires in 2 minutes", description: "Unsaved changes will be lost.", action: "Stay" },
info: { title: "New version available", description: "Reload to get the latest features.", action: "Reload" },
}
const longDescription = "This is a long message to show how the toast handles multi-line content without clipping or awkward wrapping. The title and description should both wrap cleanly."

const [type, setType] = useState("default") // or "success", "error", "warning", "info", "promise"
const [icon, setIcon] = useState(true) // the type's icon; false passes icon: null
const [description, setDescription] = useState("none") // or "short", "long"
const [action, setAction] = useState("none") // or "action", "cancel" (an action and a cancel)
const [closeButton, setCloseButton] = useState(false)
const [compact, setCompact] = useState(false)
const [persistent, setPersistent] = useState(false) // with an action or a close button

// Resolves with the saved profile after 1.5 seconds
const saveProfile = () => new Promise((resolve) => setTimeout(() => resolve({ name: "Profile" }), 1500))

// A promise ends as the default type's message: "Profile saved", its description and its action
const message = messages[type === "promise" ? "default" : type]

const show = () => {
const options = {
  description: description === "none" ? undefined : description === "short" ? message.description : longDescription,
  action: action === "none" ? undefined : { label: message.action, onClick: () => {} },
  cancel: action === "cancel" ? { label: "Cancel", onClick: () => {} } : undefined,
  closeButton,
  // Open until closed, once there is a button to close it
  duration: persistent && (action !== "none" || closeButton) ? Infinity : undefined,
  ...(compact ? compactOptions : {}),
}
if (type === "promise") {
  toast.promise(saveProfile(), { loading: "Saving…", success: (data) => `${data.name} saved`, error: "Save failed", ...options })
} else {
  // The type's icon; null leaves it out (a promise keeps its loader)
  (type === "default" ? toast : toast[type])(message.title, { ...options, icon: icon ? undefined : null })
}
}

<Button color="secondary" variant="outline" onClick={show}>
Show toast
</Button>

