const [search, setSearch] = useState("none") // where the search waits: "row" (a field under the controls) or "button" (in the bar)
const [searching, setSearching] = useState(false) // a tap opens it: its field in place of the title, with Close
const [title, setTitle] = useState(true) // false: the bar holds its controls alone
const [titleStyle, setTitleStyle] = useState("inline") // or "large", "compact-large", "compact-medium"
const [titleAlign, setTitleAlign] = useState("center") // or "start"; an inline title only
const [subtitle, setSubtitle] = useState(false) // not with a compact title
const [group, setGroup] = useState(false)
const [segmented, setSegmented] = useState(false) // a row of the bar with the views, under the search field
const [rowSize, setRowSize] = useState("md") // "lg": the large glass control
const [view, setView] = useState("all")
const [topBackground, setTopBackground] = useState("glass") // or "soft", "hard", "blur"
const [bottom, setBottom] = useState("none") // or "buttons", "search" (one search field to a screen), "action"
const [bottomBackground, setBottomBackground] = useState("soft") // or "hard", "glass", "blur"
const open = searching && search !== "none"
const named = !open && title
const compact = title && titleStyle.startsWith("compact")
const topSearch = search !== "none" // one search to a screen
const shownBottom = topSearch && bottom === "search" ? "none" : bottom
const searchButton = useRef(null)
const searchRow = useRef(null)
// Close gives the focus back to what opened the search; the row's field stays closed then (focus would open it again)
const closeSearch = () => {
  flushSync(() => setSearching(false))
  const opener = search === "button" ? searchButton.current : searchRow.current?.querySelector("input")
  if (!opener) return
  opener.dataset.restoring = ""
  opener.focus()
  delete opener.dataset.restoring
}

